//! Port of `EndCityPieces` and `EndCityStructure`.
//!
//! End cities are template pieces generated by four recursive section
//! generators (`HOUSE_TOWER_GENERATOR`, `TOWER_GENERATOR`,
//! `TOWER_BRIDGE_GENERATOR`, `FAT_TOWER_GENERATOR`). Every template comes from
//! the shipped non-village catalog at `minecraft:end_city/*`.
//!
//! The piece graph, rotations, and `random` consumption order follow Java; the
//! only intentional simplification is that placement returns chest/sentry/elytra
//! markers and entity descriptors instead of instantiating live block entities
//! or entities.

use crate::chunk::BlockState;
use crate::nbt::Tag;
use crate::worldgen::feature::{FeatureLevel, Heightmap};
use crate::worldgen::structure::StructureError;
use crate::worldgen::structure::piece::{BoundingBox, StructureDataMarker, template_bounding_box};
use crate::worldgen::structure::set::set_large_feature_seed;
use crate::worldgen::structure::start::{
    StartPlacement, StructureGenerationContext, TemplateProvider,
};
use crate::worldgen::structure::template::{
    Mirror, PlacedBlock, PlacedEntity, Rotation, StructurePlaceSettings, StructureTemplate,
    transform,
};
use folia_math::{BlockPos, Direction, Vec3};
use folia_random::{LegacyRandomSource, RandomSource};

/// `EndCityPieces.MAX_GEN_DEPTH`.
pub const MAX_GEN_DEPTH: i32 = 8;
/// `EndCityStructure` rejects a start below this Y.
pub const MIN_START_Y: i32 = 60;

const TEMPLATE_PREFIX: &str = "minecraft:end_city/";
const CHEST_LOOT: &str = "minecraft:chests/end_city_treasure";

/// `EndCityPieces.TOWER_BRIDGES`.
const TOWER_BRIDGES: [(Rotation, BlockPos); 4] = [
    (Rotation::None, BlockPos::new(1, -1, 0)),
    (Rotation::Clockwise90, BlockPos::new(6, -1, 1)),
    (Rotation::CounterClockwise90, BlockPos::new(0, -1, 5)),
    (Rotation::Clockwise180, BlockPos::new(5, -1, 6)),
];

/// `EndCityPieces.FAT_TOWER_BRIDGES`.
const FAT_TOWER_BRIDGES: [(Rotation, BlockPos); 4] = [
    (Rotation::None, BlockPos::new(4, -1, 0)),
    (Rotation::Clockwise90, BlockPos::new(12, -1, 4)),
    (Rotation::CounterClockwise90, BlockPos::new(0, -1, 8)),
    (Rotation::Clockwise180, BlockPos::new(8, -1, 12)),
];

/// One `EndCityPieces.EndCityPiece`.
#[derive(Debug, Clone, PartialEq)]
pub struct EndCityPiece {
    pub template_name: String,
    pub template: StructureTemplate,
    pub template_position: BlockPos,
    pub rotation: Rotation,
    /// `true` is `BlockIgnoreProcessor.STRUCTURE_BLOCK`; `false` also ignores
    /// air (`STRUCTURE_AND_AIR`).
    pub overwrite: bool,
    pub gen_depth: i32,
}

impl EndCityPiece {
    fn new(
        template_name: impl Into<String>,
        template: StructureTemplate,
        template_position: BlockPos,
        rotation: Rotation,
        overwrite: bool,
    ) -> Self {
        Self {
            template_name: template_name.into(),
            template,
            template_position,
            rotation,
            overwrite,
            gen_depth: 0,
        }
    }

    pub fn bounding_box(&self) -> BoundingBox {
        template_bounding_box(
            &self.template,
            self.template_position,
            self.rotation,
            BlockPos::ZERO,
            Mirror::None,
        )
    }

    fn place_settings(&self) -> StructurePlaceSettings {
        StructurePlaceSettings::new()
            .with_rotation(self.rotation)
            .with_ignore_entities(true)
            .with_ignore_air(!self.overwrite)
    }

    /// `TemplateStructurePiece.postProcess` plus `EndCityPiece.handleDataMarker`.
    pub fn place(
        &self,
        level: &mut dyn FeatureLevel,
        chunk_box: BoundingBox,
        random: &mut dyn RandomSource,
    ) -> Result<StartPlacement, StructureError> {
        let bounds = self.bounding_box();
        if !bounds.intersects(chunk_box) {
            return Ok(StartPlacement::default());
        }
        let settings = self.place_settings();
        let mut result = StartPlacement::default();
        for block in self.template.placement_blocks(&settings) {
            let pos = self.template_position.offset_by(block.pos);
            let marker = data_marker_name(block.nbt.as_ref());
            if let Some(name) = &marker
                && chunk_box.is_inside(pos)
            {
                result.data_markers.push(StructureDataMarker {
                    name: name.clone(),
                    pos,
                    nbt: block.nbt.clone(),
                });
                self.handle_data_marker(name, pos, chunk_box, &mut result, random);
            }
            if block.state.name == "minecraft:structure_block" || !chunk_box.is_inside(pos) {
                continue;
            }
            if !level.set_block(pos, block.state.clone()) {
                result.rejected += 1;
                continue;
            }
            result.written += 1;
            result.written_blocks.push(pos);
            if block.nbt.is_some() && marker.is_none() {
                result.block_entities.push(PlacedBlock { pos, ..block });
            }
        }
        result
            .written_blocks
            .sort_by_key(|pos| (pos.x(), pos.y(), pos.z()));
        result.written_blocks.dedup();
        Ok(result)
    }

    fn handle_data_marker(
        &self,
        name: &str,
        pos: BlockPos,
        chunk_box: BoundingBox,
        result: &mut StartPlacement,
        random: &mut dyn RandomSource,
    ) {
        if name.starts_with("Chest") {
            let chest_pos = pos.below();
            if chunk_box.is_inside(chest_pos) {
                let seed = random.next_long();
                let nbt = chest_nbt(seed);
                result.block_entities.push(PlacedBlock {
                    pos: chest_pos,
                    state: chest_state(),
                    nbt: Some(nbt),
                });
            }
        } else if name.starts_with("Sentry") {
            result.entities.push(entity_descriptor(
                pos,
                "minecraft:shulker",
                Vec3::new(
                    f64::from(pos.x()) + 0.5,
                    f64::from(pos.y()),
                    f64::from(pos.z()) + 0.5,
                ),
            ));
        } else if name.starts_with("Elytra") {
            let facing = self.rotation.rotate_direction(Direction::South);
            result.entities.push(item_frame_descriptor(pos, facing));
        }
    }
}

/// `EndCityStructure.generatePieces` result.
#[derive(Debug, Clone, PartialEq)]
pub struct EndCityStart {
    pieces: Vec<EndCityPiece>,
}

impl EndCityStart {
    pub fn pieces(&self) -> &[EndCityPiece] {
        &self.pieces
    }

    pub fn bounding_box(&self) -> Option<BoundingBox> {
        BoundingBox::encapsulating(self.pieces.iter().map(EndCityPiece::bounding_box))
    }

    /// `EndCityStructure.findGenerationPoint` + `generatePieces`.
    pub fn generate(
        structure_id: &str,
        context: &StructureGenerationContext<'_>,
    ) -> Result<Option<Self>, StructureError> {
        let Some(level) = context.height_source else {
            return Err(StructureError::MissingHeightSource {
                structure: structure_id.to_owned(),
            });
        };
        let mut random = LegacyRandomSource::new(0);
        set_large_feature_seed(
            &mut random,
            context.seed,
            context.chunk_pos.x,
            context.chunk_pos.z,
        );
        let rotation = Rotation::ALL[random.next_int_bound(4) as usize];
        let start_pos = lowest_y_in_5by5(context.chunk_pos, level, rotation);
        if start_pos.y() < MIN_START_Y {
            return Ok(None);
        }
        let pieces = start_house_tower(
            structure_id,
            context.templates,
            start_pos,
            rotation,
            &mut random,
        )?;
        Ok(Some(Self { pieces }))
    }

    /// Places every intersecting piece into one chunk/region box.
    pub fn place(
        &self,
        level: &mut dyn FeatureLevel,
        chunk_box: BoundingBox,
        random: &mut dyn RandomSource,
    ) -> Result<StartPlacement, StructureError> {
        let mut result = StartPlacement::default();
        for piece in &self.pieces {
            if !piece.bounding_box().intersects(chunk_box) {
                result.skipped_pieces += 1;
                continue;
            }
            let placement = piece.place(level, chunk_box, random)?;
            result.placed_pieces += 1;
            result.written += placement.written;
            result.rejected += placement.rejected;
            result.written_blocks.extend(placement.written_blocks);
            result.block_entities.extend(placement.block_entities);
            result.entities.extend(placement.entities);
            result.data_markers.extend(placement.data_markers);
        }
        result
            .written_blocks
            .sort_by_key(|pos| (pos.x(), pos.y(), pos.z()));
        result.written_blocks.dedup();
        Ok(result)
    }
}

/// `Structure.getLowestYIn5by5BoxOffset7Blocks`.
pub fn lowest_y_in_5by5(
    chunk_pos: crate::region::ChunkPos,
    level: &dyn FeatureLevel,
    rotation: Rotation,
) -> BlockPos {
    let (x_offset, z_offset) = match rotation {
        Rotation::Clockwise90 => (-5, 5),
        Rotation::Clockwise180 => (-5, -5),
        Rotation::CounterClockwise90 => (5, -5),
        Rotation::None => (5, 5),
    };
    let block_x = chunk_pos.x * 16 + 7;
    let block_z = chunk_pos.z * 16 + 7;
    let heights = [
        level.heightmap(Heightmap::WorldSurfaceWg, block_x, block_z),
        level.heightmap(Heightmap::WorldSurfaceWg, block_x, block_z + z_offset),
        level.heightmap(Heightmap::WorldSurfaceWg, block_x + x_offset, block_z),
        level.heightmap(
            Heightmap::WorldSurfaceWg,
            block_x + x_offset,
            block_z + z_offset,
        ),
    ];
    let lowest = heights
        .into_iter()
        .map(|height| height.unwrap_or_else(|| level.min_y()))
        .min()
        .unwrap_or_else(|| level.min_y());
    BlockPos::new(block_x, lowest, block_z)
}

/// `EndCityPieces.startHouseTower`.
fn start_house_tower(
    structure_id: &str,
    templates: &dyn TemplateProvider,
    start_pos: BlockPos,
    rotation: Rotation,
    random: &mut dyn RandomSource,
) -> Result<Vec<EndCityPiece>, StructureError> {
    let mut pieces = Vec::new();
    let mut piece = add_helper(
        &mut pieces,
        new_piece(
            structure_id,
            templates,
            "base_floor",
            start_pos,
            rotation,
            true,
        )?,
    );
    piece = add_helper(
        &mut pieces,
        add_piece(
            structure_id,
            templates,
            &piece,
            BlockPos::new(-1, 0, -1),
            "second_floor_1",
            rotation,
            false,
        )?,
    );
    piece = add_helper(
        &mut pieces,
        add_piece(
            structure_id,
            templates,
            &piece,
            BlockPos::new(-1, 4, -1),
            "third_floor_1",
            rotation,
            false,
        )?,
    );
    piece = add_helper(
        &mut pieces,
        add_piece(
            structure_id,
            templates,
            &piece,
            BlockPos::new(-1, 8, -1),
            "third_roof",
            rotation,
            true,
        )?,
    );
    let mut ship_created = false;
    recursive_children(
        structure_id,
        templates,
        SectionGenerator::Tower,
        1,
        &piece,
        None,
        &mut pieces,
        random,
        &mut ship_created,
    )?;
    Ok(pieces)
}

fn add_helper(pieces: &mut Vec<EndCityPiece>, piece: EndCityPiece) -> EndCityPiece {
    pieces.push(piece.clone());
    piece
}

fn add_piece(
    structure_id: &str,
    templates: &dyn TemplateProvider,
    parent: &EndCityPiece,
    start_pos: BlockPos,
    name: &str,
    rotation: Rotation,
    overwrite: bool,
) -> Result<EndCityPiece, StructureError> {
    let mut piece = new_piece(
        structure_id,
        templates,
        name,
        parent.template_position,
        rotation,
        overwrite,
    )?;
    let delta = connected_position(parent, start_pos, &piece);
    piece.template_position = piece.template_position.offset_by(delta);
    Ok(piece)
}

fn new_piece(
    structure_id: &str,
    templates: &dyn TemplateProvider,
    name: &str,
    template_position: BlockPos,
    rotation: Rotation,
    overwrite: bool,
) -> Result<EndCityPiece, StructureError> {
    let template_name = format!("{TEMPLATE_PREFIX}{name}");
    let template = templates.template(&template_name).cloned().ok_or_else(|| {
        StructureError::UnknownTemplate {
            structure: structure_id.to_owned(),
            template: template_name.clone(),
        }
    })?;
    Ok(EndCityPiece::new(
        template_name,
        template,
        template_position,
        rotation,
        overwrite,
    ))
}

/// `StructureTemplate.calculateConnectedPosition` for end-city pieces (no
/// mirror, zero pivot).
fn connected_position(
    parent: &EndCityPiece,
    start_pos: BlockPos,
    child: &EndCityPiece,
) -> BlockPos {
    let parent_pos = transform(start_pos, Mirror::None, parent.rotation, BlockPos::ZERO);
    let child_pos = transform(BlockPos::ZERO, Mirror::None, child.rotation, BlockPos::ZERO);
    parent_pos.subtract(child_pos)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SectionGenerator {
    HouseTower,
    Tower,
    TowerBridge,
    FatTower,
}

#[allow(clippy::too_many_arguments)]
fn recursive_children(
    structure_id: &str,
    templates: &dyn TemplateProvider,
    generator: SectionGenerator,
    counter: i32,
    piece: &EndCityPiece,
    start_pos: Option<BlockPos>,
    pieces: &mut Vec<EndCityPiece>,
    random: &mut dyn RandomSource,
    ship_created: &mut bool,
) -> Result<bool, StructureError> {
    if counter > MAX_GEN_DEPTH {
        return Ok(false);
    }
    let mut children = Vec::new();
    if generate_section(
        structure_id,
        templates,
        generator,
        counter,
        piece,
        start_pos,
        &mut children,
        random,
        ship_created,
    )? {
        let gen_depth = random.next_int();
        let mut collision = false;
        for child in &mut children {
            child.gen_depth = gen_depth;
            if let Some(existing) = pieces
                .iter()
                .find(|existing| existing.bounding_box().intersects(child.bounding_box()))
                && existing.gen_depth != piece.gen_depth
            {
                collision = true;
                break;
            }
        }
        if !collision {
            pieces.extend(children);
            return Ok(true);
        }
    }
    Ok(false)
}

#[allow(clippy::too_many_arguments)]
fn generate_section(
    structure_id: &str,
    templates: &dyn TemplateProvider,
    generator: SectionGenerator,
    counter: i32,
    piece: &EndCityPiece,
    start_pos: Option<BlockPos>,
    pieces: &mut Vec<EndCityPiece>,
    random: &mut dyn RandomSource,
    ship_created: &mut bool,
) -> Result<bool, StructureError> {
    match generator {
        SectionGenerator::HouseTower => {
            if counter > MAX_GEN_DEPTH {
                return Ok(false);
            }
            let rotation = piece.rotation;
            let start_pos = start_pos.unwrap_or(BlockPos::ZERO);
            let mut child = add_helper(
                pieces,
                add_piece(
                    structure_id,
                    templates,
                    piece,
                    start_pos,
                    "base_floor",
                    rotation,
                    true,
                )?,
            );
            let draw = random.next_int_bound(3);
            if draw == 0 {
                add_helper(
                    pieces,
                    add_piece(
                        structure_id,
                        templates,
                        &child,
                        BlockPos::new(-1, 4, -1),
                        "base_roof",
                        rotation,
                        true,
                    )?,
                );
            } else if draw == 1 {
                child = add_helper(
                    pieces,
                    add_piece(
                        structure_id,
                        templates,
                        &child,
                        BlockPos::new(-1, 0, -1),
                        "second_floor_2",
                        rotation,
                        false,
                    )?,
                );
                child = add_helper(
                    pieces,
                    add_piece(
                        structure_id,
                        templates,
                        &child,
                        BlockPos::new(-1, 8, -1),
                        "second_roof",
                        rotation,
                        false,
                    )?,
                );
                let _ = recursive_children(
                    structure_id,
                    templates,
                    SectionGenerator::Tower,
                    counter + 1,
                    &child,
                    None,
                    pieces,
                    random,
                    ship_created,
                )?;
            } else {
                child = add_helper(
                    pieces,
                    add_piece(
                        structure_id,
                        templates,
                        &child,
                        BlockPos::new(-1, 0, -1),
                        "second_floor_2",
                        rotation,
                        false,
                    )?,
                );
                child = add_helper(
                    pieces,
                    add_piece(
                        structure_id,
                        templates,
                        &child,
                        BlockPos::new(-1, 4, -1),
                        "third_floor_2",
                        rotation,
                        false,
                    )?,
                );
                child = add_helper(
                    pieces,
                    add_piece(
                        structure_id,
                        templates,
                        &child,
                        BlockPos::new(-1, 8, -1),
                        "third_roof",
                        rotation,
                        true,
                    )?,
                );
                let _ = recursive_children(
                    structure_id,
                    templates,
                    SectionGenerator::Tower,
                    counter + 1,
                    &child,
                    None,
                    pieces,
                    random,
                    ship_created,
                )?;
            }
            Ok(true)
        }
        SectionGenerator::Tower => {
            let rotation = piece.rotation;
            let x = 3 + random.next_int_bound(2);
            let z = 3 + random.next_int_bound(2);
            let mut child = add_helper(
                pieces,
                add_piece(
                    structure_id,
                    templates,
                    piece,
                    BlockPos::new(x, -3, z),
                    "tower_base",
                    rotation,
                    true,
                )?,
            );
            child = add_helper(
                pieces,
                add_piece(
                    structure_id,
                    templates,
                    &child,
                    BlockPos::new(0, 7, 0),
                    "tower_piece",
                    rotation,
                    true,
                )?,
            );
            let mut bridge_anchor = if random.next_int_bound(3) == 0 {
                Some(child.clone())
            } else {
                None
            };
            let count = 1 + random.next_int_bound(3);
            for index in 0..count {
                child = add_helper(
                    pieces,
                    add_piece(
                        structure_id,
                        templates,
                        &child,
                        BlockPos::new(0, 4, 0),
                        "tower_piece",
                        rotation,
                        true,
                    )?,
                );
                if index < count - 1 && random.next_boolean() {
                    bridge_anchor = Some(child.clone());
                }
            }
            if let Some(anchor) = bridge_anchor {
                for (bridge_rotation, offset) in TOWER_BRIDGES {
                    if random.next_boolean() {
                        let bridge = add_helper(
                            pieces,
                            add_piece(
                                structure_id,
                                templates,
                                &anchor,
                                offset,
                                "bridge_end",
                                rotation_add(rotation, bridge_rotation),
                                true,
                            )?,
                        );
                        let _ = recursive_children(
                            structure_id,
                            templates,
                            SectionGenerator::TowerBridge,
                            counter + 1,
                            &bridge,
                            None,
                            pieces,
                            random,
                            ship_created,
                        )?;
                    }
                }
                add_helper(
                    pieces,
                    add_piece(
                        structure_id,
                        templates,
                        &child,
                        BlockPos::new(-1, 4, -1),
                        "tower_top",
                        rotation,
                        true,
                    )?,
                );
            } else if counter == 7 {
                add_helper(
                    pieces,
                    add_piece(
                        structure_id,
                        templates,
                        &child,
                        BlockPos::new(-1, 4, -1),
                        "tower_top",
                        rotation,
                        true,
                    )?,
                );
            } else {
                return recursive_children(
                    structure_id,
                    templates,
                    SectionGenerator::FatTower,
                    counter + 1,
                    &child,
                    None,
                    pieces,
                    random,
                    ship_created,
                );
            }
            Ok(true)
        }
        SectionGenerator::TowerBridge => {
            let rotation = piece.rotation;
            let count = random.next_int_bound(4) + 1;
            let mut child = add_helper(
                pieces,
                add_piece(
                    structure_id,
                    templates,
                    piece,
                    BlockPos::new(0, 0, -4),
                    "bridge_piece",
                    rotation,
                    true,
                )?,
            );
            let last = pieces.len() - 1;
            pieces[last].gen_depth = -1;
            let mut y = 0;
            for _ in 0..count {
                if random.next_boolean() {
                    child = add_helper(
                        pieces,
                        add_piece(
                            structure_id,
                            templates,
                            &child,
                            BlockPos::new(0, y, -4),
                            "bridge_piece",
                            rotation,
                            true,
                        )?,
                    );
                    y = 0;
                } else {
                    if random.next_boolean() {
                        child = add_helper(
                            pieces,
                            add_piece(
                                structure_id,
                                templates,
                                &child,
                                BlockPos::new(0, y, -4),
                                "bridge_steep_stairs",
                                rotation,
                                true,
                            )?,
                        );
                    } else {
                        child = add_helper(
                            pieces,
                            add_piece(
                                structure_id,
                                templates,
                                &child,
                                BlockPos::new(0, y, -8),
                                "bridge_gentle_stairs",
                                rotation,
                                true,
                            )?,
                        );
                    }
                    y = 4;
                }
            }
            if !*ship_created && random.next_int_bound(10 - counter) == 0 {
                add_helper(
                    pieces,
                    add_piece(
                        structure_id,
                        templates,
                        &child,
                        BlockPos::new(
                            -8 + random.next_int_bound(8),
                            y,
                            -70 + random.next_int_bound(10),
                        ),
                        "ship",
                        rotation,
                        true,
                    )?,
                );
                *ship_created = true;
            } else if !recursive_children(
                structure_id,
                templates,
                SectionGenerator::HouseTower,
                counter + 1,
                &child,
                Some(BlockPos::new(-3, y + 1, -11)),
                pieces,
                random,
                ship_created,
            )? {
                return Ok(false);
            }
            add_helper(
                pieces,
                add_piece(
                    structure_id,
                    templates,
                    &child,
                    BlockPos::new(4, y, 0),
                    "bridge_end",
                    rotation_add(rotation, Rotation::Clockwise180),
                    true,
                )?,
            );
            let last = pieces.len() - 1;
            pieces[last].gen_depth = -1;
            Ok(true)
        }
        SectionGenerator::FatTower => {
            let rotation = piece.rotation;
            let mut child = add_helper(
                pieces,
                add_piece(
                    structure_id,
                    templates,
                    piece,
                    BlockPos::new(-3, 4, -3),
                    "fat_tower_base",
                    rotation,
                    true,
                )?,
            );
            child = add_helper(
                pieces,
                add_piece(
                    structure_id,
                    templates,
                    &child,
                    BlockPos::new(0, 4, 0),
                    "fat_tower_middle",
                    rotation,
                    true,
                )?,
            );
            let mut index = 0;
            while index < 2 && random.next_int_bound(3) != 0 {
                index += 1;
                child = add_helper(
                    pieces,
                    add_piece(
                        structure_id,
                        templates,
                        &child,
                        BlockPos::new(0, 8, 0),
                        "fat_tower_middle",
                        rotation,
                        true,
                    )?,
                );
                for (bridge_rotation, offset) in FAT_TOWER_BRIDGES {
                    if random.next_boolean() {
                        let bridge = add_helper(
                            pieces,
                            add_piece(
                                structure_id,
                                templates,
                                &child,
                                offset,
                                "bridge_end",
                                rotation_add(rotation, bridge_rotation),
                                true,
                            )?,
                        );
                        let _ = recursive_children(
                            structure_id,
                            templates,
                            SectionGenerator::TowerBridge,
                            counter + 1,
                            &bridge,
                            None,
                            pieces,
                            random,
                            ship_created,
                        )?;
                    }
                }
            }
            add_helper(
                pieces,
                add_piece(
                    structure_id,
                    templates,
                    &child,
                    BlockPos::new(-2, 8, -2),
                    "fat_tower_top",
                    rotation,
                    true,
                )?,
            );
            Ok(true)
        }
    }
}

/// `Rotation.getRotated`.
fn rotation_add(first: Rotation, second: Rotation) -> Rotation {
    let value = first as i32 + second as i32;
    Rotation::ALL[(value & 3) as usize]
}

fn data_marker_name(nbt: Option<&Tag>) -> Option<String> {
    let nbt = nbt?;
    if nbt.get("id").and_then(Tag::as_str) != Some("minecraft:structure_block") {
        return None;
    }
    if nbt.get("mode").and_then(Tag::as_str) != Some("DATA")
        && nbt.get("mode").and_then(Tag::as_str) != Some("data")
    {
        return None;
    }
    Some(
        nbt.get("metadata")
            .and_then(Tag::as_str)
            .unwrap_or_default()
            .to_owned(),
    )
}

fn chest_nbt(seed: i64) -> Tag {
    Tag::Compound(vec![
        ("id".to_owned(), Tag::String("minecraft:chest".to_owned())),
        ("LootTable".to_owned(), Tag::String(CHEST_LOOT.to_owned())),
        ("LootTableSeed".to_owned(), Tag::Long(seed)),
    ])
}

fn chest_state() -> BlockState {
    BlockState {
        name: "minecraft:chest".to_owned(),
        properties: vec![("facing".to_owned(), "north".to_owned())],
    }
}

fn entity_descriptor(pos: BlockPos, id: &str, exact: Vec3) -> PlacedEntity {
    PlacedEntity {
        pos: exact,
        block_pos: pos,
        nbt: Some(entity_nbt(id, exact)),
    }
}

fn item_frame_descriptor(pos: BlockPos, facing: Direction) -> PlacedEntity {
    let facing_byte = match facing {
        Direction::Down => 0,
        Direction::Up => 1,
        Direction::North => 2,
        Direction::South => 3,
        Direction::West => 4,
        Direction::East => 5,
    };
    let mut nbt = entity_nbt(
        "minecraft:item_frame",
        Vec3::new(f64::from(pos.x()), f64::from(pos.y()), f64::from(pos.z())),
    );
    if let Tag::Compound(fields) = &mut nbt {
        fields.push(("Facing".to_owned(), Tag::Byte(facing_byte)));
        fields.push((
            "Item".to_owned(),
            Tag::Compound(vec![
                ("id".to_owned(), Tag::String("minecraft:elytra".to_owned())),
                ("count".to_owned(), Tag::Int(1)),
            ]),
        ));
    }
    PlacedEntity {
        pos: Vec3::new(f64::from(pos.x()), f64::from(pos.y()), f64::from(pos.z())),
        block_pos: pos,
        nbt: Some(nbt),
    }
}

fn entity_nbt(id: &str, pos: Vec3) -> Tag {
    Tag::Compound(vec![
        ("id".to_owned(), Tag::String(id.to_owned())),
        (
            "Pos".to_owned(),
            Tag::List(vec![
                Tag::Double(pos.x),
                Tag::Double(pos.y),
                Tag::Double(pos.z),
            ]),
        ),
    ])
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::worldgen::feature::FeatureLevel;

    struct MockLevel {
        min_y: i32,
        height: i32,
        fixed_height: Option<i32>,
    }

    impl FeatureLevel for MockLevel {
        fn min_y(&self) -> i32 {
            self.min_y
        }

        fn height(&self) -> i32 {
            self.height
        }

        fn get_block(&self, _pos: BlockPos) -> Option<&BlockState> {
            None
        }

        fn set_block(&mut self, _pos: BlockPos, _state: BlockState) -> bool {
            false
        }

        fn heightmap(&self, _kind: Heightmap, _x: i32, _z: i32) -> Option<i32> {
            self.fixed_height
        }
    }

    #[test]
    fn rotation_table_is_the_java_order() {
        assert_eq!(
            rotation_add(Rotation::None, Rotation::Clockwise90),
            Rotation::Clockwise90
        );
        assert_eq!(
            rotation_add(Rotation::Clockwise180, Rotation::Clockwise180),
            Rotation::None
        );
        assert_eq!(
            rotation_add(Rotation::CounterClockwise90, Rotation::Clockwise90),
            Rotation::None
        );
    }

    #[test]
    fn lowest_y_uses_the_rotated_five_by_five_corners() {
        let level = MockLevel {
            min_y: 0,
            height: 384,
            fixed_height: Some(80),
        };
        let pos = lowest_y_in_5by5(crate::region::ChunkPos::new(1, 2), &level, Rotation::None);
        assert_eq!(pos, BlockPos::new(23, 80, 39));
    }
}
